oxy_webhelp_navlinks = {"salesforce_data_protection-d39307e44816":{"topics":[{"title":"Monitoring Salesforce organizations","shortdesc":"<p class=\"shortdesc\">View details about a Salesforce instance to monitor the data changes, backup jobs,         status, backup summary, and license usage.<\/p>","href":"salesforce\/monitoring_salesforce_organizations.html","attributes":{"data-id":"monitoring_salesforce_organizations"},"menu":{"hasChildren":false},"tocID":"monitoring_salesforce_organizations-d39307e44830","next":"monitoring_salesforce_organizations-d39307e44830"},{"title":"Supported Salesforce organizations, editions, products, and APIs","shortdesc":"<p class=\"shortdesc\">Information about supported Salesforce organizations, editions, products, and APIs         for data protection and archiving.<\/p>","href":"salesforce\/salesforce_supported_data_types.html","attributes":{"data-id":"salesforce_supported_data_types"},"menu":{"hasChildren":false},"tocID":"salesforce_supported_data_types-d39307e44854","topics":[]},{"title":"Supported regions for Salesforce","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> provides support for Salesforce protection in several regions.         You select the region when you set up the Salesforce instance in <span class=\"ph\">RSC<\/span>.<\/p>","href":"salesforce\/salesforce_regions.html","attributes":{"data-id":"salesforce_regions"},"menu":{"hasChildren":false},"tocID":"salesforce_regions-d39307e44865","topics":[]},{"title":"Salesforce APIs","shortdesc":"<p class=\"shortdesc\">Rubrik accesses a Salesforce organization using APIs. Before a scheduled backup or         restore job starts, <span class=\"ph\">RSC<\/span> checks API availability. <span class=\"ph\">RSC<\/span> also         monitors API usage throughout each job and throttles operations to remain within the         assigned API limits.<\/p>","href":"salesforce\/salesforce_apis.html","attributes":{"data-id":"salesforce_apis"},"menu":{"hasChildren":false},"tocID":"salesforce_apis-d39307e44881","topics":[]},{"title":"Salesforce permissions for backup and recovery","shortdesc":"<p class=\"shortdesc\">Backing up and restoring data requires that you assign certain Salesforce permissions         for user account authentication in Salesforce.<\/p>","href":"salesforce\/salesforce_permissions.html","attributes":{"data-id":"salesforce_permissions"},"menu":{"hasChildren":false},"tocID":"salesforce_permissions-d39307e44898","next":"salesforce_permissions-d39307e44898"},{"title":"Salesforce object coverage","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> protects a wide range of Salesforce objects, with specific limits         for unsupported objects, metadata types, recovery behavior, and schema changes.<\/p>","href":"salesforce\/salesforce_object_coverage.html","attributes":{"data-id":"salesforce_object_coverage"},"menu":{"hasChildren":false},"tocID":"salesforce_object_coverage-d39307e44969","topics":[]},{"title":"Table of RBAC privileges for Salesforce Data Protection","shortdesc":"<p class=\"shortdesc\">Accessing Salesforce protection features within <span class=\"ph\">RSC<\/span> requires the         appropriate RBAC permissions. You can use the default Salesforce Admin role or a custom         role.<\/p>","href":"salesforce\/salesforce_rbac.html","attributes":{"data-id":"salesforce_rbac"},"menu":{"hasChildren":false},"tocID":"salesforce_rbac-d39307e44982","topics":[]},{"title":"Viewing <span class=\"ph\">RSC<\/span> outbound IP addresses for Salesforce","shortdesc":"<p class=\"shortdesc\">View the complete list of IP addresses that <span class=\"ph\">RSC<\/span> uses to connect to         your Salesforce organization, and add them to your network allowlist.<\/p>","href":"salesforce\/salesforce_viewing_outbound_ips.html","attributes":{"data-id":"salesforce_viewing_outbound_ips"},"menu":{"hasChildren":false},"tocID":"salesforce_viewing_outbound_ips-d39307e44996","topics":[]},{"title":"Adding a Salesforce organization","shortdesc":"<p class=\"shortdesc\">Add a Salesforce organization to back up the data in your organization.<\/p>","href":"salesforce\/salesforce_adding_organization.html","attributes":{"data-id":"salesforce_adding_organization"},"menu":{"hasChildren":false},"tocID":"salesforce_adding_organization-d39307e45013","topics":[]},{"title":"Removing Salesforce organizations","shortdesc":"<p class=\"shortdesc\">Remove a Salesforce organization to remove all snapshots and configurations from <span class=\"ph\">RSC<\/span>.<\/p>","href":"salesforce\/salesforce_removing_org.html","attributes":{"data-id":"salesforce_removing_org"},"menu":{"hasChildren":false},"tocID":"salesforce_removing_org-d39307e45024","topics":[]},{"title":"Reauthenticating your Salesforce account","shortdesc":"<p class=\"shortdesc\">Reauthenticate your Salesforce account when Salesforce revokes authentication after a         while or when the account used to authenticate is no longer active in the Salesforce         site.<\/p>","href":"salesforce\/salesforce_reauthenticating_account.html","attributes":{"data-id":"salesforce_reauthenticating_account"},"menu":{"hasChildren":false},"tocID":"salesforce_reauthenticating_account-d39307e45039","topics":[]},{"title":"Monitoring API usage for Salesforce","shortdesc":"<p class=\"shortdesc\">View and monitor the Bulk 2.0 and REST API usage details over a period of time from         the API Usage page.<\/p>","href":"salesforce\/salesforce_monitoring_api.html","attributes":{"data-id":"salesforce_monitoring_api"},"menu":{"hasChildren":false},"tocID":"salesforce_monitoring_api-d39307e45050","next":"salesforce_monitoring_api-d39307e45050"},{"title":"Salesforce backup and recovery","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> securely backs up your Salesforce organization with snapshots and         recovers your data from those snapshots.<\/p>","href":"salesforce\/salesforce_backup_recovery.html","attributes":{"data-id":"salesforce_backup_recovery"},"menu":{"hasChildren":false},"tocID":"salesforce_backup_recovery-d39307e45086","next":"salesforce_backup_recovery-d39307e45086"},{"title":"Salesforce Right to Be Forgotten","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> anonymizes personally identifiable information in Salesforce         backup data during restore and seeding operations to support privacy compliance. This is         known as the Right to Be Forgotten feature.<\/p>","href":"salesforce\/salesforce_right_to_be_forgotten.html","attributes":{"data-id":"salesforce_right_to_be_forgotten"},"menu":{"hasChildren":false},"tocID":"salesforce_right_to_be_forgotten-d39307e45400","next":"salesforce_right_to_be_forgotten-d39307e45400"},{"title":"Salesforce data analysis","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> generates insights about the changes in Salesforce data and         metadata, facilitating detailed monitoring and secure restore operations.<\/p>","href":"salesforce\/salesforce_data_analysis.html","attributes":{"data-id":"salesforce_data_analysis"},"menu":{"hasChildren":false},"tocID":"salesforce_data_analysis-d39307e45546","next":"salesforce_data_analysis-d39307e45546"},{"title":"Data masking templates","shortdesc":"<p class=\"shortdesc\">A data masking template defines data fields and the methods to prevent the exposure         of sensitive data when recovering a production snapshot to a non-production         environment.<\/p>","href":"salesforce\/salesforce_data_masking_templates.html","attributes":{"data-id":"salesforce_data_masking_templates"},"menu":{"hasChildren":false},"tocID":"salesforce_data_masking_templates-d39307e45650","next":"salesforce_data_masking_templates-d39307e45650"},{"title":"Salesforce archiving","shortdesc":"<p class=\"shortdesc\">Salesforce archiving enables you to move inactive or aged records out of your         Salesforce production organization into lower-cost durable storage while preserving record         content, relationships, and accessibility.<\/p>","href":"salesforce\/salesforce_archiving.html","attributes":{"data-id":"salesforce_archiving"},"menu":{"hasChildren":false},"tocID":"salesforce_archiving-d39307e45754","next":"salesforce_archiving-d39307e45754"},{"title":"Salesforce dashboard details","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> monitors Salesforce data and displays details such as API and         license usage, and the number of failed or successful backups.<\/p>","href":"salesforce\/salesforce_dashboard_details_2.html","attributes":{"data-id":"salesforce_dashboard_details"},"menu":{"hasChildren":false},"tocID":"salesforce_dashboard_details-d39307e45911","topics":[]},{"title":"Salesforce backup indexing strategy","shortdesc":"<p class=\"shortdesc\"><span class=\"ph\">RSC<\/span> uses an optimized indexing strategy during Salesforce full         backups to reduce backup time and make backed-up data available for search and filter         operations.<\/p>","href":"salesforce\/sf_backup_indexing_strategy.html","attributes":{"data-id":"sf_backup_indexing_strategy"},"menu":{"hasChildren":false},"tocID":"sf_backup_indexing_strategy-d39307e45924","topics":[]}]}};